      "concepts": [
        "free learning",
        "free practice",
        "free skill credentials",
        "paid proctored exam",
        "ROI",
        "recognition",
        "overlap",
        "opportunity cost"
      ],
      "sections": [
        {
          "heading": "Categories are not interchangeable",
          "paragraphs": [],
          "items": [
            "Prefer free learning when it teaches the needed capability.",
            "Use free practice for gaps rather than inflated completion claims.",
            "Assess free skill credentials by recognition and actual task value.",
            "Pay for an exam only after its current path and expected value have been checked.",
            "An optional specialization must not displace the core architect path without a deliberate global-priority decision."
          ]
        }
      ],
